DECLARE p jsonb := $payload${"ley":{"id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","titulo":"Reglamento de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos","siglas":"RLEPEPM","fecha_publicacion":"2025-12-03","fecha_ultima_reforma":null,"vigente":true,"temas_clave":["Petróleos Mexicanos","Consejo de Administración","Régimen especial"],"url_original":"https://www.diputados.gob.mx/LeyesBiblio/regley/Reg_LEPEPM.pdf","tipo":"reglamento"},"articulos":[{"id":"f5c70676-e079-58e3-a6ce-443c35960e07","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":0,"identificador":"Preámbulo y expedición","contenido":"DECRETO por el que se expide el Reglamento de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos.\n\nAl margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.\n\nCLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, en ejercicio de la facultad que me confiere el artículo 89, fracción I de la Constitución Política de los Estados Unidos Mexicanos, y con fundamento en los artículos 31, 32 Bis, 33, 37 y 38 Bis de la Ley Orgánica de la Administración Pública Federal, y 6, 19, 22, 84, fracción I y demás aplicables de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos, he tenido a bien expedir el siguiente\n\nDECRETO POR EL QUE SE EXPIDE EL REGLAMENTO DE LA LEY DE LA EMPRESA PÚBLICA DEL ESTADO, PETRÓLEOS MEXICANOS\n\nARTÍCULO ÚNICO. Se expide el Reglamento de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos, para quedar como sigue:\n\nREGLAMENTO DE LA LEY DE LA EMPRESA PÚBLICA DEL ESTADO, PETRÓLEOS MEXICANOS","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null},{"id":"47151026-37ef-5493-a3b9-12bebcae2adf","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":1,"identificador":"Artículo 1","contenido":"El presente reglamento tiene por objeto regular la aplicación y debida observancia de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos, el cual es de observancia obligatoria para esta empresa pública del Estado y quienes mantengan relación con ella.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO PRIMERO — DE PETRÓLEOS MEXICANOS COMO EMPRESA PÚBLICA DEL ESTADO","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"8956fa41-b5ca-5248-b686-79ce3d548524","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":2,"identificador":"Artículo 2","contenido":"Para los efectos de este reglamento, en singular o plural, se entiende por:\n\nI. Comité Especial: El previsto en el artículo 26 de la Ley;\n\nII. Consejo de Administración: El Consejo de Administración de Petróleos Mexicanos;\n\nIII. Ley: La Ley de la Empresa Pública del Estado, Petróleos Mexicanos;\n\nIV. Persona Comisaria: La persona encargada de realizar la evaluación anual de Petróleos Mexicanos a la que se refiere el artículo 125 de la Ley;\n\nV. Personas Consejeras: Las personas integrantes del Consejo de Administración a que se refiere el artículo 18, fracciones I a V de la Ley, y\n\nVI. Personas Consejeras Independientes: Las personas integrantes del Consejo de Administración a que se refiere el artículo 18, fracción VI de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO PRIMERO — DE PETRÓLEOS MEXICANOS COMO EMPRESA PÚBLICA DEL ESTADO","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"57f8d270-eca0-5aa7-9996-6d1256c6905c","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":3,"identificador":"Artículo 3","contenido":"La interpretación de este reglamento corresponde a la Secretaría de Energía.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO PRIMERO — DE PETRÓLEOS MEXICANOS COMO EMPRESA PÚBLICA DEL ESTADO","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"d38e255c-f640-5927-a696-fd3bcb691777","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":4,"identificador":"Artículo 4","contenido":"Las personas que sean designadas como Personas Consejeras Independientes, deben entregar previamente a la Consejería Jurídica del Ejecutivo Federal, la documentación que acredite el cumplimiento de los requisitos previstos en el artículo 23 de la Ley, así como un escrito en el que manifiesten, bajo protesta de decir verdad, que conocen y cumplen dichos requisitos para ser designadas como Personas Consejeras Independientes, y que no se ubican en alguno de los supuestos de impedimento o conflicto de interés previstos en la Ley o en este reglamento.\n\nEl escrito mencionado debe incluir una descripción detallada de su trayectoria académica, los empleos, cargos o comisiones que hayan desempeñado y de los servicios profesionales brindados con anterioridad, así como las funciones más relevantes desempeñadas que acrediten su capacidad, habilidades o pericia para ser designadas.\n\nAsimismo, debe señalar si se han desempeñado como personas consejeras en empresas competidoras de Petróleos Mexicanos o de sus empresas filiales, o si les han prestado servicios de asesoría o representación, en términos del artículo 23, último párrafo de la Ley.\n\nLa información y documentación a la que se refiere este artículo debe estar disponible para consulta en el portal de Internet de Petróleos Mexicanos.\n\nLas Personas Consejeras Independientes que durante su encargo dejen de cumplir con alguno de los requisitos señalados en el artículo 23 de la Ley, o les sobrevenga algún impedimento de los previstos en el artículo 24 del citado ordenamiento, deben hacerlo del conocimiento de la persona titular del Ejecutivo Federal, por conducto de la Consejería Jurídica del Ejecutivo Federal, para que actúe en lo conducente.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"db7e4ff0-6ab9-5b35-82f1-62c10bc0b1bf","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":5,"identificador":"Artículo 5","contenido":"Las personas designadas como Personas Consejeras Independientes, conforme al artículo 18 de la Ley, deben manifestar por escrito su consentimiento a tal designación a la persona titular del Ejecutivo Federal, por conducto de la Consejería Jurídica del Ejecutivo Federal.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"c5e8c925-9931-5761-bd03-969559f3dd37","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":6,"identificador":"Artículo 6","contenido":"Las Personas Consejeras deben comunicar por escrito a la persona que preside el Consejo de Administración, la designación de las personas servidoras públicas suplentes que pueden asistir a las sesiones del Consejo de Administración y de sus comités.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"f1c51714-d263-5724-bc76-81e3fed3a4e0","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":7,"identificador":"Artículo 7","contenido":"Para el nombramiento por un periodo adicional de una Persona Consejera Independiente, pueden considerarse las recomendaciones y observaciones al desempeño que emita la Auditoría Superior de la Federación, el informe a que se refiere el artículo 121 de la Ley, y la evaluación que realice la Persona Comisaria a que se refiere el artículo 125, fracción I del mismo ordenamiento, así como los demás informes relativos al desempeño operativo y financiero de Petróleos Mexicanos que se estimen convenientes.\n\nLa Persona Consejera Independiente que sea nombrada para un periodo adicional, debe presentar nuevamente a la Consejería Jurídica del Ejecutivo Federal la documentación que acredite el cumplimiento de los requisitos previstos en la Ley y en este reglamento, con su información actualizada para su ratificación por el Senado de la República.\n\nLo dispuesto en los párrafos anteriores, así como el procedimiento establecido en el artículo 4 de este reglamento, también aplica para las Personas Consejeras Independientes que cubran vacantes, en términos de lo previsto en el artículo 25 segundo párrafo de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"863f5737-ebca-5631-aa67-7ed18d451d04","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":8,"identificador":"Artículo 8","contenido":"La documentación presentada o recabada para la remoción de una Persona Consejera Independiente es pública a partir de que la persona titular del Ejecutivo Federal la determina, en los términos establecidos en la normatividad en materia de transparencia y protección de datos personales.\n\nLa persona titular del Ejecutivo Federal debe enviar al Senado de la República el expediente correspondiente de la remoción de la Persona Consejera Independiente de que se trate.\n\nLa Persona Consejera Independiente que se encuentre en procedimiento de remoción está impedida para conocer y votar los asuntos que se sometan a consideración del Consejo de Administración y de sus comités, hasta en tanto el Senado de la República apruebe o niegue la remoción correspondiente.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"443e6e91-0235-56d7-9385-cccb96474b54","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":9,"identificador":"Artículo 9","contenido":"La responsabilidad en que incurran las Personas Consejeras y las Personas Consejeras Independientes, a que se refiere el artículo 33 de la Ley, es exigible por las vías jurisdiccionales establecidas en el último párrafo del citado precepto, con independencia del inicio o conclusión del procedimiento de remoción que sea aplicable.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"0c3b2e55-a74f-5b4c-805e-514403e968d8","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":10,"identificador":"Artículo 10","contenido":"Las disposiciones contenidas en la Ley y en el presente reglamento, relacionadas con las responsabilidades, deberes y obligaciones, así como lo relativo a los impedimentos y al conflicto de interés de las personas integrantes del Consejo de Administración, son aplicables a las personas suplentes que se designen en términos de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"f0aa4c91-3b0f-58e0-addf-997b61ca70b9","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":11,"identificador":"Artículo 11","contenido":"Las Personas Consejeras y las Personas Consejeras Independientes, además de cumplir con lo señalado en la Ley, deben abstenerse de:\n\nI. Tener en Petróleos Mexicanos o en sus empresas filiales un empleo, cargo o comisión;\n\nII. Prestar servicios profesionales, formar parte del consejo directivo o de administración, o ser persona empleada de empresas nacionales o extranjeras que sean del mismo giro o industria de Petróleos Mexicanos o de sus empresas filiales, o que compitan con cualquiera de estas;\n\nIII. Adquirir o poseer bonos de deuda, obligaciones, papel comercial o cualquier otro tipo de instrumento bursátil emitido o garantizado por Petróleos Mexicanos o sus empresas filiales, salvo que se trate de inversiones en el mercado de valores a través de fondos o sociedades de inversión, o cuando, mediante cualquier otro instrumento, no tenga poder de decisión sobre dicha inversión. Esta salvedad es aplicable para sus familiares en línea directa;\n\nIV. Recibir directa o indirectamente cualquier tipo de beneficio, ingreso o compensación por parte de Petróleos Mexicanos o de sus empresas filiales, distinto al derivado del ejercicio de sus funciones como personas integrantes del Consejo de Administración;\n\nV. Presidir o formar parte del consejo directivo, patronato, consejo de administración o cualquier órgano análogo o equivalente, o ser persona empleada de una fundación, universidad, asociación civil o sociedad civil que reciba o haya recibido donativos o donaciones por parte de Petróleos Mexicanos o de sus empresas filiales, que le representen más del cincuenta por ciento del total recibido por dichos conceptos durante el año calendario inmediato anterior, siempre y cuando, con motivo de sus funciones en la fundación, universidad, asociación civil o sociedad civil, tenga la posibilidad de gestionar directa o indirectamente, la obtención de los donativos o donaciones, disponer sobre su aplicación o recibir un beneficio directo o indirecto, por sí o a través de sus familiares en línea directa, y\n\nVI. Realizar o desempeñar cualquier empleo, cargo, comisión, actividad o prestación de servicios, directa o indirectamente, bajo cualquier figura o modalidad, que represente un conflicto de interés, por significar una interferencia con el debido y adecuado desempeño de sus funciones como Personas Consejeras o Personas Consejeras Independientes.\n\nPara efectos de lo previsto en el artículo 19, párrafo segundo de la Ley, el impedimento señalado se refiere a cualquier empleo, cargo o comisión, sin importar el poder o ente público de los órdenes de gobierno mencionados en dicho artículo, con excepción de aquellos de docencia o de investigación.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"825156fc-181e-5915-856f-42759e186b98","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":12,"identificador":"Artículo 12","contenido":"Las personas integrantes del Consejo de Administración y sus suplentes deben presentar ante la Secretaría Anticorrupción y Buen Gobierno y el Consejo, durante el mes de enero de cada año, un escrito en el que manifiesten, bajo protesta de decir verdad, que no se ubican en alguno de los supuestos de impedimento o conflicto de interés a que se refieren la Ley y el presente reglamento, el cual incluye las demás actividades profesionales, empleos, puestos, cargos o comisiones que hayan desempeñado en el año calendario inmediato anterior, así como todos aquellos contratos de asesoría o los que en ejercicio de sus actividades profesionales hayan celebrado de forma personal o en los que hubiesen participado, durante el mismo periodo.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"700778e4-6164-5e9b-97f1-b83f98e028ad","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":13,"identificador":"Artículo 13","contenido":"Petróleos Mexicanos y sus filiales, a través de la empresa pública del Estado, deben entregar a la Secretaría Anticorrupción y Buen Gobierno y a la Unidad de Responsabilidades, cuando así le sea solicitado, copia de cualquier información que haya proporcionado a las autoridades competentes, nacionales o extranjeras, relacionada con las actividades actuales y anteriores de las personas integrantes del Consejo de Administración, en términos de este reglamento y la normativa en materia de protección de datos personales.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"7dc10d7c-cbfc-5ff8-a951-88ad1a3d09a3","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":14,"identificador":"Artículo 14","contenido":"En caso de que, a juicio de al menos dos personas integrantes del Consejo de Administración o de la Persona Comisaria, las actividades, empleos, puestos, cargos, comisiones o contratos señalados en el escrito a que se refiere el artículo 12 del presente reglamento, puedan configurar un conflicto de interés, deben remitir a la Secretaría Anticorrupción y Buen Gobierno el dictamen correspondiente, a efecto de que, de confirmarse el conflicto de interés, solicite al Consejo de Administración la remoción a que hace referencia el artículo 39 de la Ley.\n\nLa determinación que se adopte conforme al párrafo anterior debe ser sin perjuicio de las acciones legales que, en su caso, resulten procedentes.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"95e6d445-fccb-5b27-abcf-b63651d96273","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":15,"identificador":"Artículo 15","contenido":"Se considera que las personas integrantes del Consejo de Administración no incurren en conflicto de interés cuando:\n\nI. Realicen actividades altruistas, culturales o de beneficencia, salvo lo dispuesto en el artículo 11, fracción V de este reglamento;\n\nII. Realicen actividades por las que no perciban remuneración, viáticos, expensa o beneficio económico de cualquier especie, siempre que no estén vinculadas con las industrias o actividades que formen parte del objeto de Petróleos Mexicanos o sus empresas filiales, y\n\nIII. Dicten conferencias a título personal o participen en otros foros; impartan cátedra o realicen cualquier otra actividad docente en instituciones públicas y privadas, siempre que no revelen información a la que tengan acceso con motivo de sus funciones como personas integrantes del Consejo de Administración, con excepción de aquella que sea pública.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"fdbf0c49-c043-54fe-95d0-5d0167f8379f","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":16,"identificador":"Artículo 16","contenido":"Para efectos de lo establecido en el artículo 24, fracción VI de la Ley, no se considera la pertenencia a juntas directivas de personas morales cuyo objeto principal sea la realización de actividades culturales, altruistas o sin fines de lucro, siempre y cuando no impida el adecuado ejercicio de su función como Persona Consejera Independiente.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"a4f44a89-58b8-5471-84d4-12701b98f05b","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":17,"identificador":"Artículo 17","contenido":"En el supuesto de que, de la evaluación anual a que se refiere el artículo 125 de la Ley, realizada por la Persona Comisaria, esta detecte un posible caso de conflicto de interés, debe elaborar y remitir inmediatamente a la Secretaría Anticorrupción y Buen Gobierno el dictamen correspondiente.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","seccion_nombre":null},{"id":"e031b9b4-0832-58fa-9412-8a1cae72cdc1","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":18,"identificador":"Artículo 18","contenido":"La presidencia del Comité Especial es anual y rotatoria entre el representante de la Secretaría de Hacienda y Crédito Público que elija su titular, y el representante de la Secretaría de Energía. El orden debe ser acordado por los titulares de las dependencias.\n\nLa presidencia del Comité Especial es responsable de convocar a las sesiones que se celebren y enviar la convocatoria correspondiente cuando menos con diez días naturales de anticipación.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Tercero — Del Comité Especial","seccion_nombre":null},{"id":"350542f0-a6d2-5c44-9ea5-debe12030c5b","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":19,"identificador":"Artículo 19","contenido":"Las decisiones del Comité Especial deben constar en el acta de cada sesión que se formalice para tal efecto, misma que debe incluir las razones y motivos que sirven de base para su adopción, y deben tomar en consideración lo dispuesto en el artículo 26, párrafo tercero de la Ley y, en su caso, en el artículo 22 de este reglamento.\n\nLas actas de las sesiones deben ser firmadas por las tres personas integrantes del Comité Especial y deben remitirse a la persona titular de la Dirección General de Petróleos Mexicanos, para los efectos correspondientes.\n\nLas resoluciones del Comité Especial son aplicables a Petróleos Mexicanos a partir de su notificación.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Tercero — Del Comité Especial","seccion_nombre":null},{"id":"f7fdbdd0-95b5-5127-a91e-26b6a7d01ab8","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":20,"identificador":"Artículo 20","contenido":"Las personas que funjan como suplentes de las Personas Consejeras en el Consejo de Administración, no pueden ser designadas como personas integrantes del Comité Especial.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Tercero — Del Comité Especial","seccion_nombre":null},{"id":"4faeb341-5a35-5431-b42d-5b559ce0bc53","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":21,"identificador":"Artículo 21","contenido":"Las remuneraciones de las Personas Consejeras Independientes y de la Persona Comisaria deben ser establecidas por el Comité Especial y ser cubiertas con cargo a Petróleos Mexicanos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Cuarto — De las Remuneraciones","seccion_nombre":null},{"id":"fe1f188f-5901-5525-84ce-39694ea7ddce","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":22,"identificador":"Artículo 22","contenido":"Para determinar la remuneración de las Personas Consejeras Independientes y de la Persona Comisaria, se deben considerar los lineamientos que para tal efecto emita el Comité Especial, los cuales deben observar lo previsto en el artículo 26, párrafo tercero de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Cuarto — De las Remuneraciones","seccion_nombre":null},{"id":"7b1b07d5-ccd6-5071-b45f-4d55a27b2417","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":23,"identificador":"Artículo 23","contenido":"El Consejo de Administración, a propuesta debidamente justificada y presentada por al menos dos de sus integrantes, puede establecer los comités que considere necesarios para el desarrollo eficiente de las actividades de Petróleos Mexicanos, con independencia de los previstos en el artículo 42 de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Quinto — De los Comités","seccion_nombre":null},{"id":"b6820cfe-0326-5ad8-b9a7-e4243c076480","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":24,"identificador":"Artículo 24","contenido":"Las reglas de operación de cada uno de los comités deben delimitar la integración, las funciones, la operación y las actividades que deben realizar en términos de lo previsto por la Ley. Para tales efectos, las citadas reglas deben contener como mínimo, lo siguiente:\n\nI. Las funciones de la persona titular de la presidencia;\n\nII. Las funciones de la persona titular de la secretaría;\n\nIII. Tipos de sesiones que pueden celebrar;\n\nIV. Quórum necesario para la celebración de sus sesiones y la toma de decisiones;\n\nV. Contenido de las convocatorias para la celebración de sesiones;\n\nVI. Disposiciones generales de operación de los comités;\n\nVII. Contenido de las actas que deben levantarse en cada sesión;\n\nVIII. La solicitud y plazo de entrega de la información a que se refiere el artículo 43, segundo párrafo de la Ley, y\n\nIX. Las disposiciones que se consideren necesarias para el adecuado funcionamiento administrativo de los comités.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","capitulo_nombre":"Capítulo Quinto — De los Comités","seccion_nombre":null},{"id":"87ec4a4d-696b-5eed-958d-a8f571de097e","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":25,"identificador":"Artículo 25","contenido":"Las normas de auditoría aplicables a Petróleos Mexicanos y, en su caso, a sus empresas filiales, conforme a lo previsto en el artículo 55, fracción V de la Ley pueden ser, sin limitación, alguna de las siguientes:\n\nI. Las Normas Internacionales de Auditoría emitidas por la Federación Internacional de Contadores;\n\nII. Las Normas Internacionales de Información Financiera emitidas por el Consejo de Normas Internacionales de Contabilidad;\n\nIII. Las Normas de Información Financiera emitidas por el Consejo Mexicano de Normas de Información Financiera, y\n\nIV. Las Normas de Auditoría, emitidas por el Instituto Mexicano de Auditores Internos y por el Instituto Mexicano de Contadores Públicos.\n\nTratándose de las auditorías internas a que se refiere el artículo 58 de la Ley, además de aplicar las normas a que se refieren las fracciones anteriores en lo conducente, debe aplicar aquellas que emita el Consejo de Administración en materia de fiscalización y auditorías.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO TERCERO — VIGILANCIA Y AUDITORÍA","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"3263e38b-42f4-5310-ba54-15a42a0456cc","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":26,"identificador":"Artículo 26","contenido":"La persona auditora externa que sea designada por el Consejo de Administración, en términos del artículo 60 de la Ley, debe acreditar que cuenta con las certificaciones relacionadas con el ámbito de su actuación como persona auditora y no haber sido inhabilitada previamente, entre otras disposiciones, en términos de la Ley General de Responsabilidades Administrativas, la Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público y la Ley de Obras Públicas y Servicios Relacionados con las\n\nMismas.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO TERCERO — VIGILANCIA Y AUDITORÍA","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"3a007fb7-5137-5902-914e-018e9de4e826","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":27,"identificador":"Artículo 27","contenido":"Para la fiscalización y el desarrollo de las auditorías que realiza la Auditoría Superior de la Federación previstas en el artículo 61 de la Ley, todas las áreas de Petróleos Mexicanos deben facilitar el desarrollo de las actividades de vigilancia y auditoría.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO TERCERO — VIGILANCIA Y AUDITORÍA","capitulo_nombre":"Capítulo Único — Disposiciones Generales","seccion_nombre":null},{"id":"529b1cb2-9235-567e-889e-df7d8d66f3cf","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":28,"identificador":"Artículo 28","contenido":"El Consejo de Administración es responsable de establecer las normas para la constitución, escisión, fusión o liquidación de empresas filiales, la alineación de sus actividades al Programa de Desarrollo de Petróleos Mexicanos, y las instancias de aprobación, ejecución, seguimiento y la adopción de mejores prácticas para el fortalecimiento institucional.\n\nLas contrataciones que realicen las empresas filiales están sujetas a los criterios y lineamientos que al efecto emita Petróleos Mexicanos, a través del Consejo de Administración.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Primero — De las Empresas Filiales","seccion_nombre":null},{"id":"04383bfa-5d24-5ed5-bc01-f9e5c3ae3d8a","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":29,"identificador":"Artículo 29","contenido":"Para efectos de lo dispuesto en el artículo 70 de la Ley, Petróleos Mexicanos, a través de las personas representantes, personas consejeras o personas mandatarias en las empresas filiales, debe realizar las gestiones necesarias para que en sus consejos de administración se adopten las medidas conducentes para la alineación estratégica de sus actividades al Programa de Desarrollo de Petróleos Mexicanos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Primero — De las Empresas Filiales","seccion_nombre":null},{"id":"2b9dbb59-58b3-50b6-94ec-63e9d19ac826","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":30,"identificador":"Artículo 30","contenido":"Para efectos de los artículos 16, fracción VII y 114 de la Ley, Petróleos Mexicanos, a través de las personas representantes, personas consejeras o personas mandatarias en las empresas filiales, debe llevar a cabo las gestiones que se requieran ante las instancias de estas para que adopten las medidas establecidas en el Programa de Cumplimiento Legal.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Primero — De las Empresas Filiales","seccion_nombre":null},{"id":"cc8ebbe5-79f7-50e8-9e8f-3b5e4d5eee9a","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":31,"identificador":"Artículo 31","contenido":"En los casos en que las secretarías de Energía y de Hacienda y Crédito Público decidan ejercer las atribuciones señaladas en el artículo 66 de la Ley, deben comunicar por escrito la designación a la persona secretaria del Consejo de Administración, previamente a la celebración de la sesión correspondiente. Tratándose de una sesión ordinaria del Consejo de Administración, debe comunicarse a más tardar dos días hábiles previo a la convocatoria y, en caso de una sesión extraordinaria, debe comunicarse al inicio de la sesión. En ambos casos se debe hacer constar en el acta respectiva.\n\nLa participación de las personas consejeras representantes de las secretarías de Energía y de Hacienda y Crédito Público en las empresas filiales, debe preverse en sus estatutos sociales. Lo anterior, sin perjuicio de que dichos instrumentos pueden ser modificados o reformados.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Primero — De las Empresas Filiales","seccion_nombre":null},{"id":"672655f6-7cd5-54d0-9128-2de775baf495","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":32,"identificador":"Artículo 32","contenido":"Los lineamientos de austeridad en el gasto y uso de recursos, a que se refiere el artículo 16, fracción XXXVII de la Ley, deben considerar, además de lo previsto en el artículo 76 de la Ley, las medidas de disciplina y austeridad que debe observar Petróleos Mexicanos en el ejercicio y gasto de su presupuesto, y que coadyuve a que los recursos económicos que disponga, se administren conforme a los principios de eficacia, eficiencia, economía, transparencia y honradez, conforme a lo dispuesto por el artículo 134, párrafo primero de la Constitución Política de los Estados Unidos Mexicanos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Segundo — De las Remuneraciones y Austeridad","seccion_nombre":null},{"id":"f96b26a0-7f40-53a3-8355-0a8fc2e853e7","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":33,"identificador":"Artículo 33","contenido":"Para efectos de lo dispuesto en el artículo 77 de la Ley, conforme a lo establecido en los lineamientos de austeridad en el gasto y uso de recursos, la persona titular de la Dirección General de Petróleos Mexicanos debe proponer anualmente, para autorización del Consejo de Administración, programas de austeridad en el gasto y uso de recursos que contengan metas específicas, los cuales deben considerar los principios de austeridad previstos en la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Segundo — De las Remuneraciones y Austeridad","seccion_nombre":null},{"id":"1934b604-a17d-5877-817e-d71952a3112a","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":34,"identificador":"Artículo 34","contenido":"Al final de cada ejercicio fiscal, Petróleos Mexicanos debe entregar al Consejo de Administración, para su conocimiento, un informe en el que se identifiquen los ahorros obtenidos por la aplicación de lo previsto en los lineamientos de austeridad en el gasto y uso de recursos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Segundo — De las Remuneraciones y Austeridad","seccion_nombre":null},{"id":"ee37bfb0-53e2-5adf-a54e-fd79b34cc3a0","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":35,"identificador":"Artículo 35","contenido":"Para efectos de lo dispuesto en el artículo 80, segundo párrafo de la Ley, en los procedimientos de contratación, para la adjudicación de un contrato mediante concurso abierto, pueden utilizarse distintos mecanismos, como subastas ascendentes, subastas descendentes, o subastas al primer precio en sobre cerrado, entre otros, incluso las previstas en la Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público y la Ley de Obras Públicas y Servicios Relacionados con las Mismas, así como los criterios de adjudicación que garanticen la igualdad de condiciones para todas las personas participantes, que al efecto determine el Consejo de Administración, de conformidad con los principios y disposiciones a que se refiere el artículo 79 de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"a6559db6-c1bc-5245-9000-842cb7c77921","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":36,"identificador":"Artículo 36","contenido":"Para efectos de lo previsto en el artículo 81, fracción VI de la Ley, entre otros supuestos, se pueden realizar contrataciones mediante adjudicación directa o invitación restringida cuando el monto de cada operación que se pretende realizar no exceda de un millón de pesos en el primer caso, y de cuatro millones setecientos mil pesos en el segundo. Dichos montos deben actualizarse anualmente conforme al Índice Nacional de Precios al Consumidor.\n\nLos procedimientos de invitación restringida y de adjudicación directa a que se refiere este artículo, pueden emplearse siempre que las operaciones no se fraccionen con el objeto de quedar comprendidas dentro de los umbrales señalados y que la suma de operaciones en un ejercicio fiscal no rebase el treinta por ciento del presupuesto total autorizado para adquisiciones, arrendamientos, servicios y obras.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"1d85bc12-f4b2-507f-b9e1-4ad697dfcfb7","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":37,"identificador":"Artículo 37","contenido":"Para efectos de lo dispuesto en el artículo 86, fracción II, inciso c) de la Ley, Petróleos Mexicanos puede celebrar convenios de colaboración con las autoridades competentes en materia fiscal y en materia laboral.\n\nLas personas interesadas en contratar con Petróleos Mexicanos deben manifestar por escrito su anuencia para que las autoridades a que se refiere el párrafo anterior entreguen la información necesaria para evaluar los requisitos señalados en el artículo 86, fracción II, inciso c) de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"9da123ec-3696-56ac-8080-7912318a62c1","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":38,"identificador":"Artículo 38","contenido":"Para los efectos del artículo 79, fracción VI, inciso d) de la Ley, Petróleos Mexicanos puede celebrar los convenios de colaboración que se requieran con la Secretaría Anticorrupción y Buen Gobierno.\n\nEn la política de contrataciones el Consejo de Administración debe considerar, como criterio de fortalecimiento institucional para evaluar las prácticas de los proveedores, que los que sean personas morales cuenten, preferentemente, con una política de integridad que asuma los elementos a que se refiere el artículo 25 de la Ley General de Responsabilidades Administrativas.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"b0ec4747-b526-5ec7-9a8d-9d268100de8c","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":39,"identificador":"Artículo 39","contenido":"Para efectos de lo dispuesto en el artículo 89 de la Ley, en los casos en que se detecten probables irregularidades por actos u omisiones de personas servidoras públicas o particulares durante los procesos de contratación de Petróleos Mexicanos, incluidas las invitaciones restringidas y adjudicaciones directas, se debe dar vista a la Unidad de Responsabilidades, para que actúe en términos de las disposiciones aplicables.\n\nEn todo caso, la Unidad de Responsabilidades puede proponer a la Secretaría Anticorrupción y Buen Gobierno los asuntos que por su relevancia deban ser atraídos.\n\nLo anterior, sin perjuicio de las medidas que se deben adoptar en términos de las políticas y lineamientos que emita el Consejo de Administración.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"782fdb85-d5f8-5741-8dee-18b17c8d8b18","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":40,"identificador":"Artículo 40","contenido":"Para los efectos del artículo 84, fracción I de la Ley, el recurso de reconsideración tiene por objeto revocar, modificar o confirmar, total o parcialmente y, en definitiva, el fallo o la determinación que declare desierto, total o parcialmente, el concurso o la invitación restringida.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"1f79358f-e803-5a40-b3df-ca00d8abab03","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":41,"identificador":"Artículo 41","contenido":"La instancia colegiada que se determine en el Estatuto Orgánico de la Empresa Pública del Estado, Petróleos Mexicanos es la encargada de tramitar y resolver el recurso de reconsideración previsto en este capítulo, para lo cual debe contar con un área responsable de la instrucción cuya función principal es sustanciar el procedimiento en términos de lo que disponga el presente reglamento y conforme a las atribuciones que el Estatuto Orgánico de la Empresa Pública del Estado, Petróleos Mexicanos le confiera.\n\nLas determinaciones emitidas durante la tramitación de los recursos de reconsideración, ya sea por la instancia colegiada o por el área responsable de la instrucción, no admiten recurso alguno.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"c56bafc2-e1e6-5ee2-976e-15e9b7226eca","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":42,"identificador":"Artículo 42","contenido":"El recurso de reconsideración debe presentarse por escrito ante la instancia colegiada, dentro de los cinco días hábiles siguientes a la celebración de la junta pública en que se dé a conocer el fallo o la determinación que declare desierto un procedimiento de contratación, o que se le haya notificado a la persona ofertante, en los casos en que no se celebre junta pública.\n\nLa interposición del recurso de reconsideración en forma diversa o ante autoridad distinta a las señaladas en el párrafo anterior, no interrumpe el plazo para su oportuna presentación.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"10a03949-c493-508d-9267-f144ef0d23dd","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":43,"identificador":"Artículo 43","contenido":"Solo pueden interponer el recurso de reconsideración quienes hayan presentado ofertas en el procedimiento de contratación impugnado y únicamente respecto de las partidas para las que se hayan presentado ofertas.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"1f577810-8399-592c-b96e-2dd1ce3a5803","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":44,"identificador":"Artículo 44","contenido":"Tratándose de oferta conjunta, todos los que hayan presentado la oferta deben suscribir el escrito en que se interponga el recurso de reconsideración y para el caso de no hacerlo, debe tenerse por no interpuesto, salvo que lo presente la persona representante común que, en su caso, designen por escrito desde el inicio del procedimiento de contratación.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"f33a121b-ba66-513a-8e4a-271f91f406ed","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":45,"identificador":"Artículo 45","contenido":"El recurso de reconsideración debe presentarse mediante escrito y debe contener los siguientes requisitos:\n\nI. A quién se dirige;\n\nII. El nombre de la persona recurrente y, en su caso, de la que promueve en su nombre, quien debe acompañar un original o copia certificada del instrumento público que acredite su representación.\n\nTratándose de las personas concursantes que hayan presentado propuesta conjunta y no hubieren nombrado una persona representante común al inicio del procedimiento de contratación, deben\n\ndesignar una persona representante común en el escrito inicial en que promuevan el recurso de reconsideración; de lo contrario, se entiende que funge como tal la persona nombrada primeramente en dicho escrito de recurso;\n\nIII. Domicilio para recibir notificaciones personales, el cual debe estar ubicado en el lugar en que resida la instancia colegiada, o correo electrónico para tales efectos, así como el nombre o nombres de la persona o personas autorizadas para recibirlas. En caso de no señalar domicilio o correo electrónico, se debe notificar por lista, la cual debe fijarse en un lugar visible y de fácil acceso determinado por la instancia colegiada, y levantar el acta circunstanciada correspondiente;\n\nIV. El acto que se recurre, la fecha de su emisión y, en su caso, la fecha de notificación de dicho acto;\n\nV. El nombre o denominación y domicilio de la persona a quien se le adjudica el contrato, a quien se le considera como persona tercera interesada;\n\nVI. Los hechos u omisiones que constituyen los antecedentes del acto impugnado;\n\nVII. Los agravios que estima se le causan;\n\nVIII. Las pruebas que ofrece, mismas que deben estar relacionadas con los hechos, omisiones y agravios señalados en su impugnación, así como con el objeto del recurso de reconsideración. Tratándose de documentales que formen parte del procedimiento de contratación y que obren en poder de la convocante, basta con que se ofrezcan para que esta última deba remitirlas en copia autorizada al momento de rendir su informe, y\n\nIX. La firma autógrafa de quien lo promueve.\n\nSe deben exhibir copias del escrito y de sus anexos para la convocante y la persona tercera interesada, en caso de haberla. Para el caso de que se omita acompañar la documentación antes señalada, debe prevenirse a la persona recurrente para que la exhiba dentro de los tres días hábiles siguientes a aquel en que surta efectos la notificación respectiva; en caso de no hacerlo, el recurso debe tenerse por no presentado.\n\nAsimismo, en caso de que la persona recurrente hubiere omitido alguno de los requisitos o documentos señalados en las fracciones I, II, primer párrafo, IV y V de este artículo, se le debe prevenir para que en un plazo de tres días hábiles siguientes a aquel en que surta efectos la notificación respectiva, los subsane o exhiba la documentación correspondiente; apercibida de que, de no hacerlo en el plazo señalado, se debe desechar el recurso de reconsideración.\n\nEl recurso de reconsideración no admite ampliaciones y debe ser resuelto con los agravios expresados en el escrito inicial.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"cb6e5ee2-3924-56ac-b42e-bd8e2ab595e0","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":46,"identificador":"Artículo 46","contenido":"La suspensión de la ejecución del fallo que adjudique el contrato y los actos que de este deriven, debe concederse siempre y cuando:\n\nI. Lo solicite expresamente la persona recurrente;\n\nII. Se cumpla con los requisitos a que se refiere el artículo 45 del presente reglamento, y\n\nIII. No se siga perjuicio al interés social o se contravengan disposiciones de orden público.\n\nEn su solicitud, la persona recurrente debe expresar las razones por las cuales estima procedente la suspensión, así como la afectación que puede ocasionarle la ejecución del fallo.\n\nLa suspensión puede solicitarse en cualquier momento, hasta antes de que se dicte la resolución que ponga fin al recurso de reconsideración.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"b24bde63-2350-5549-bf48-5db8493b755d","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":47,"identificador":"Artículo 47","contenido":"Cuando la instancia colegiada que conozca del recurso de reconsideración advierta que existen o pueden existir actos contrarios a las disposiciones jurídicas aplicables, debe ordenar de oficio la suspensión de la ejecución del fallo de adjudicación, siempre y cuando no se haya emitido la resolución del recurso.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"e33d7806-3545-5d96-b1d9-fdb34ab5d203","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":48,"identificador":"Artículo 48","contenido":"La instancia colegiada debe resolver sobre el otorgamiento de la suspensión dentro de los cinco días hábiles siguientes a la recepción del informe que rinda la convocante y, en caso de que no se resuelva en el término señalado, debe entenderse negada la suspensión.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"9ea00aae-5849-54fe-8169-ceb9e73d07ee","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":49,"identificador":"Artículo 49","contenido":"En los casos en que proceda la suspensión, pero que de concederse pueda ocasionar daños o perjuicios a la convocante o a la persona tercera interesada, la persona recurrente debe otorgar garantía, dentro de los tres días hábiles siguientes a la notificación de la resolución respectiva, para reparar el daño e indemnizar los posibles perjuicios que con la suspensión se causen, cuando no obtenga resolución favorable en el recurso de reconsideración.\n\nLa instancia colegiada debe determinar el monto de la garantía, mismo que no debe ser menor al diez, ni mayor al treinta por ciento del monto de la propuesta económica de la persona recurrente o de las partidas impugnadas, y cuando no sea posible determinar dicho monto, el porcentaje se fija en relación con el presupuesto autorizado para la contratación que corresponda o al monto de las partidas que, en su caso, correspondan.\n\nDe no exhibirse la garantía requerida en el plazo a que se refiere el párrafo primero de este artículo, deja de surtir efectos la suspensión.\n\nLa suspensión decretada queda sin efectos si la persona tercera interesada otorga una contragarantía equivalente a la que exhibe la persona recurrente.\n\nNo se admite la contragarantía cuando de ejecutarse el acto impugnado quede sin materia el recurso de reconsideración.\n\nLa suspensión deja de surtir efectos una vez que sea resuelto el recurso de reconsideración, sin necesidad de declaración alguna.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"f097a4cb-1598-5b6a-b429-ccbe1ebc7856","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":50,"identificador":"Artículo 50","contenido":"El recurso de reconsideración se tiene por no interpuesto cuando:\n\nI. Se presenta ante la instancia colegiada fuera del plazo establecido en el artículo 42 del presente reglamento;\n\nII. No se expresen agravios, o\n\nIII. No se encuentre suscrito con firma autógrafa original por la persona facultada para ello.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"ff4c7b7e-48aa-5cee-9a6b-4bbd8f3e39c7","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":51,"identificador":"Artículo 51","contenido":"El recurso de reconsideración es improcedente:\n\nI. Contra actos materia de otro medio de impugnación pendiente de resolución, promovido por la misma persona recurrente y contra el mismo acto impugnado;\n\nII. Contra actos que no afectan los intereses jurídicos de la persona recurrente; se considera que los actos del procedimiento de contratación no afectan los intereses jurídicos de la persona recurrente, entre otros casos, cuando esta no haya presentado oferta en el concurso;\n\nIII. Contra actos consentidos expresamente;\n\nIV. Cuando el acto impugnado no pueda surtir efecto legal o material alguno por haber dejado de existir el objeto o la materia del recurso de reconsideración, o del procedimiento de contratación del cual deriva el recurso de reconsideración, o se haya ejecutado en su totalidad el contrato concursado;\n\nV. Cuando la persona recurrente opte por hacer valer la acción jurisdiccional a que se refiere el artículo 84, fracción II de la Ley;\n\nVI. Tratándose de actos resueltos previamente, mediante recurso de reconsideración, sin importar que el sentido de la resolución no se pronuncie respecto del fondo del asunto;\n\nVII. Cuando no se promueva contra el fallo o la determinación que da por terminado el procedimiento de contratación por declararlo desierto;\n\nVIII. Cuando se promueva en contra de actos que no formen parte del procedimiento de contratación, y\n\nIX. Cuando se promueva en contra de actos derivados de procedimientos emitidos por autoridades distintas a la convocante.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"3c759804-619d-50b7-8095-ab0577c7afcf","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":52,"identificador":"Artículo 52","contenido":"El recurso de reconsideración se sobresee cuando:\n\nI. La persona recurrente se desista expresamente del recurso;\n\nII. Durante el procedimiento sobrevenga alguna de las causales de improcedencia a que se refiere el artículo anterior, o\n\nIII. La persona recurrente muera o se extinga durante la tramitación del recurso, siempre que el fallo reclamado solo afecte a su persona.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"3d138a08-4d61-54f6-8970-7cfc82be54fc","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":53,"identificador":"Artículo 53","contenido":"Las notificaciones del recurso de reconsideración se hacen:\n\nI. En forma personal o por correo electrónico, para la persona recurrente y para la persona tercera interesada, en los siguientes casos:\n\na) La primera notificación y las prevenciones;\n\nb) Las resoluciones que conceden o nieguen la suspensión;\n\nc) La resolución definitiva, y\n\nd) Las demás determinaciones o resoluciones que lo ameriten, a juicio de la instancia colegiada que conoce del recurso de reconsideración;\n\nII. Por lista, conforme a lo señalado en el artículo 45, fracción III de este reglamento, en los casos no previstos en la fracción anterior, o bien, cuando no se señale domicilio o correo electrónico por la persona recurrente o la persona tercera interesada, ubicado en el lugar en que reside la instancia colegiada. La lista debe ser fijada en un lugar visible y de fácil acceso determinado por la instancia colegiada, y se debe levantar acta circunstanciada de la fijación correspondiente, y\n\nIII. Por oficio, aquellas dirigidas a la convocante, mismas que pueden ser remitidas por correo electrónico.\n\nLas notificaciones surten efectos el mismo día en que son practicadas.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"ab376f1e-6f77-5ce4-b54c-4c1592238580","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":54,"identificador":"Artículo 54","contenido":"Admitido el recurso de reconsideración, debe requerirse a la convocante que rinda en el plazo de cinco días hábiles un informe circunstanciado, en el que exponga las razones y fundamentos para sostener la improcedencia del recurso, así como la validez o legalidad del acto que se impugna y debe acompañar, en su caso, el soporte de las justificaciones emitidas por el área requirente, así como copia autorizada por la convocante de las constancias necesarias para apoyar dicho informe y de aquella documentación a que se refiere el artículo 45, fracción VIII de este reglamento.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"8acb9cec-9c35-562d-9c8e-05d1c4d6216c","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":55,"identificador":"Artículo 55","contenido":"Una vez conocidos los datos de la persona tercera interesada, debe corrérsele traslado con copia del escrito inicial y sus anexos, a efecto de que, dentro de los cinco días hábiles siguientes, comparezca al procedimiento a manifestar lo que a su derecho convenga y a ofrecer pruebas, en cuyo caso es aplicable, en lo conducente, lo dispuesto por el artículo 45 de este reglamento.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"681fa765-0261-5f58-be10-5a9f2c17f680","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":56,"identificador":"Artículo 56","contenido":"Son admisibles toda clase de pruebas con excepción de la confesional a cargo de autoridades. Los medios de convicción pueden desecharse cuando no fuesen ofrecidos conforme a derecho, no tengan relación con el fondo del asunto, sean improcedentes o innecesarios o contrarios a la moral y el derecho.\n\nEn el ofrecimiento de las pruebas, las partes deben cumplir los requisitos y formalidades establecidos para cada una de ellas en el Código Federal de Procedimientos Civiles, o aquel que lo sustituya.\n\nTratándose de pruebas que requieran ulterior desahogo, una vez admitidas, el área encargada de la tramitación de los recursos de reconsideración debe señalar fecha y hora para la realización de los actos necesarios para ello y autorizar a las personas servidoras públicas que los deben llevar a cabo.\n\nDesahogadas las pruebas, se tiene por cerrada la instrucción y las partes tienen un plazo de cinco días hábiles para formular alegatos por escrito ante la instancia colegiada, contados a partir del día siguiente al cierre de la instrucción. Vencido dicho plazo la instancia colegiada que conoce del recurso de reconsideración debe dictar la resolución en un plazo de quince días hábiles y en su contra no procede recurso administrativo alguno.\n\nEn la resolución que emita la instancia colegiada, puede declarar que los agravios resultan inoperantes para decretar la revocación o modificación del fallo o la determinación que concluya el concurso o invitación restringida, cuando las violaciones alegadas no resulten suficientes para afectar su contenido.\n\nCuando el fallo o la determinación impugnados sean revocados por la instancia colegiada, los contratos derivados de este, y cuya adjudicación haya sido impugnada, son válidos y exigibles hasta en tanto se da cumplimiento a la resolución. Es necesario terminar los contratos anticipadamente cuando la reposición de actos implique que debe adjudicarse a una persona concursante diversa, deba declararse desierto o cancelado el procedimiento, o se decrete su nulidad total.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"bf30ab79-9ddc-5439-a686-a84be7509aed","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":57,"identificador":"Artículo 57","contenido":"La convocante, con la participación del área requirente del procedimiento de contratación, en el ámbito de sus respectivas competencias, deben acatar la resolución que ponga fin al recurso de reconsideración en los términos resueltos por la instancia colegiada en un plazo de diez días hábiles, lo cual se debe informar a esta última dentro de los tres días hábiles siguientes a la fecha del cumplimiento. Solo puede suspenderse la ejecución de las resoluciones de la instancia colegiada, mediante determinación de autoridad administrativa o jurisdiccional competente, debidamente notificada a la instancia colegiada.\n\nSi la convocante no cumple en sus términos la resolución, la persona recurrente o la persona tercera interesada, deben hacerlo del conocimiento de la instancia colegiada que conozca y resuelva el recurso de reconsideración para que requiera el cumplimiento y, en su caso, dé vista a la Unidad de Responsabilidades en Petróleos Mexicanos para que proceda en términos de la Ley General de Responsabilidades Administrativas.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"43855514-4584-5214-8350-263f70d70327","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":58,"identificador":"Artículo 58","contenido":"A partir de que cause estado la resolución que pone fin al recurso de reconsideración y dentro de un plazo de tres meses, puede iniciarse el incidente de ejecución de garantía o contragarantía, mismo que debe tramitarse por escrito ante la instancia colegiada que conoce dicho recurso.\n\nEn el referido escrito deben señalarse el daño o perjuicio que produce la suspensión de la suscripción del contrato o los actos que se hubieran realizado por levantarse la suspensión como consecuencia de la contragarantía otorgada por la persona tercera interesada, y se deben ofrecer las pruebas que se estimen pertinentes. De no presentarse dentro del plazo indicado en el párrafo anterior, debe procederse a la devolución o cancelación, en su caso, de la garantía o contragarantía, según el caso.\n\nCon el escrito incidental debe darse vista a la persona interesada que otorgó la garantía o contragarantía, según corresponda, a efecto de que, dentro del plazo de diez días hábiles, manifieste lo que a su derecho convenga y presente las pruebas correspondientes.\n\nUna vez desahogadas las pruebas, las partes tienen un plazo de tres días hábiles para formular alegatos por escrito, contados a partir del día siguiente al acuerdo respectivo. Vencido el plazo para formular alegatos, en el plazo de diez días hábiles, la instancia colegiada que conoce del recurso de reconsideración debe resolver el incidente planteado, y debe determinar la procedencia de cancelar, o bien, de hacer efectiva la garantía o contragarantía de que se trate, según se acredite el daño o perjuicio causado por la suspensión de la suscripción del contrato, o por la continuación de los actos, según corresponda.\n\nLa garantía o contragarantía solamente deben hacerse efectivas una vez que quede firme la resolución que se dicte en el incidente de ejecución que corresponda.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"fa4c2601-6f1e-5de8-b288-21cfefac9b53","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":59,"identificador":"Artículo 59","contenido":"En lo no previsto en el presente capítulo, resultan aplicables de manera supletoria, la Ley Federal de Procedimiento Administrativo y el Código Federal de Procedimientos Civiles o aquellos que los sustituyan, en este orden.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","seccion_nombre":null},{"id":"9e1297b8-477e-599d-a0f7-f85ff9dc7521","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":60,"identificador":"Artículo 60","contenido":"Las personas titulares de la Unidad de Responsabilidades en Petróleos Mexicanos y de sus áreas de denuncias e investigaciones y de responsabilidades, deben ser nombradas y removidas conforme a lo dispuesto en el Reglamento Interior de la Secretaría Anticorrupción y Buen Gobierno.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Cuarto — De las Responsabilidades Administrativas","seccion_nombre":null},{"id":"9735fd86-c0b8-5117-a9a0-edbb486bed85","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":61,"identificador":"Artículo 61","contenido":"Para efectos de lo establecido en el artículo 93 de la Ley, en materia de responsabilidades administrativas se debe estar a lo siguiente:\n\nI. La Unidad de Responsabilidades en Petróleos Mexicanos está a cargo de la persona titular designada por la Secretaría Anticorrupción y Buen Gobierno quien, para la tramitación, desahogo y resolución de los asuntos de su competencia, se auxilia de las áreas siguientes:\n\na) Denuncias e investigaciones, y\n\nb) Responsabilidades.\n\nLa Secretaría Anticorrupción y Buen Gobierno puede determinar una organización diversa a la prevista en esta fracción, acorde a las políticas en recursos humanos, de remuneraciones y de austeridad de Petróleos Mexicanos, y\n\nII. Las personas titulares de la Unidad de Responsabilidades en Petróleos Mexicanos y de las áreas a que se refiere la fracción anterior tienen las atribuciones que la Ley Orgánica de la Administración Pública Federal, la Ley General de Responsabilidades Administrativas, el Reglamento Interior de la Secretaría Anticorrupción y Buen Gobierno y demás disposiciones aplicables, otorgan a las personas titulares de los órganos internos de control y a las áreas de denuncias e investigaciones y de responsabilidades.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Cuarto — De las Responsabilidades Administrativas","seccion_nombre":null},{"id":"c607178f-4567-5f6a-ad2a-32315b7e7d13","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":62,"identificador":"Artículo 62","contenido":"Las personas servidoras públicas de Petróleos Mexicanos incluidas aquellas que ejerzan funciones o tomen decisiones en las empresas filiales, están sujetas a la Ley General de Responsabilidades Administrativas, en concordancia con el último párrafo del artículo 94 de la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Cuarto — De las Responsabilidades Administrativas","seccion_nombre":null},{"id":"bb4ff81b-df0a-5ae9-a512-a2361add9090","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":63,"identificador":"Artículo 63","contenido":"Los recursos aportados, contenidos y obtenidos en fideicomisos, mandatos o contratos análogos, que se rigen por las disposiciones jurídicas de derecho privado, no deben integrarse al balance financiero, ni al techo de gasto establecidos en el artículo 100 de la Ley.\n\nLa constitución, celebración y operación de fideicomisos, de mandatos o contratos análogos en los que se aporten recursos económicos distintos a los considerados en el Presupuesto de Egresos de la Federación del ejercicio fiscal correspondiente, que al efecto autorice el Consejo de Administración, se deben regir por las disposiciones jurídicas aplicables.\n\nLa información y documentación con que cuente o solicite Petróleos Mexicanos en relación con los fideicomisos, mandatos o contratos análogos a que se refiere este artículo, se deben sujetar a las disposiciones de control y auditoría que determine el Consejo de Administración, sin perjuicio de las demás disposiciones jurídicas que le resulten aplicables.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Quinto — Del Presupuesto","seccion_nombre":null},{"id":"ee0451ba-f979-57e2-948e-95373aad99ef","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":64,"identificador":"Artículo 64","contenido":"Petróleos Mexicanos, a través del área que corresponda, debe realizar los registros de las cuentas por los conceptos de presupuesto y gasto de los recursos económicos destinados a cumplir con las obligaciones señaladas en los artículos 133, fracción VII y 152, último párrafo de la Ley del Sector Hidrocarburos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Quinto — Del Presupuesto","seccion_nombre":null},{"id":"a588a606-54d2-5a0e-b1f6-35b1fafca0a0","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":65,"identificador":"Artículo 65","contenido":"La propuesta global de financiamiento a que se refiere el artículo 107, fracción I de la Ley, debe entregarse a la Secretaría de Hacienda y Crédito Público a más tardar el quince de julio de cada año.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Sexto — De la Deuda","seccion_nombre":null},{"id":"f259c847-7391-5bdf-a73c-d940f1bc16b4","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":66,"identificador":"Artículo 66","contenido":"Para los efectos de lo dispuesto en los artículos 16, fracción VI, 49, fracción VI y 50, fracción IV de la Ley, el Plan de Sostenibilidad de Petróleos Mexicanos debe estar alineado con la Estrategia Nacional de Transición Energética, el Plan para la Transición Energética y el Aprovechamiento Sustentable de la Energía, el Plan de Desarrollo del Sector Eléctrico y el Plan de Desarrollo del Sector Hidrocarburos de la Secretaría de Energía, el Programa de Desarrollo de Petróleos Mexicanos, los compromisos internacionales que el Estado mexicano haya firmado en materia energética y ambiental, así como con los estándares aceptados a nivel nacional e internacional.\n\nPetróleos Mexicanos debe contar con las áreas y recursos necesarios para proponer, desarrollar y verificar, en su caso, los programas y actividades en materia de sostenibilidad, con independencia de las atribuciones conferidas al Comité de Sostenibilidad.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","capitulo_nombre":"Capítulo Séptimo — De la Sostenibilidad","seccion_nombre":null},{"id":"26d7175e-a566-59fe-b645-e2222f0ecf5a","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":67,"identificador":"Artículo 67","contenido":"Para los efectos de lo previsto en el artículo 125 de la Ley, la evaluación anual a cargo de la Persona Comisaria debe realizarse conforme a las mejores prácticas en la materia, así como procurar que los resultados de la evaluación y los reportes que deriven de esta, sean comparables en el tiempo.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Primera — De la Persona Comisaria"},{"id":"1143ecab-d637-5fdf-8127-ef75d0e233aa","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":68,"identificador":"Artículo 68","contenido":"Para los efectos del artículo 125, párrafo tercero de la Ley, el contrato de prestación de servicios profesionales que se celebre con la Persona Comisaria designada, se debe formalizar entre esta y Petróleos Mexicanos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Primera — De la Persona Comisaria"},{"id":"d14b5af8-64a2-5121-bb4a-294a2900d7e7","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":69,"identificador":"Artículo 69","contenido":"Para efectos del artículo 28, fracción VIII de la Ley, la Persona Comisaria debe participar en las sesiones del Consejo de Administración, salvo que dicha participación pueda comprometer o afectar su imparcialidad e independencia en el ejercicio de su función evaluadora o en los casos en que ello implique un conflicto de interés.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Primera — De la Persona Comisaria"},{"id":"15c458b0-913f-5a8c-aea7-d32d9949c4ed","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":70,"identificador":"Artículo 70","contenido":"Para efectos de lo dispuesto en el artículo 125, fracción I de la Ley, el informe que se entregue a la Cámara de Diputados y a la persona titular del Ejecutivo Federal no debe incluir información que se encuentre protegida por los secretos comercial o industrial, así como la demás que se encuentre clasificada como reservada o confidencial en términos de la Ley General de Transparencia y Acceso a la Información Pública.\n\nA más tardar el 30 de marzo de cada año, las secretarías de Energía, de Hacienda y Crédito Público, y Anticorrupción y Buen Gobierno, pueden solicitar a la Persona Comisaria que en la evaluación anual que formule respecto del ejercicio anterior, analice o evalúe aspectos específicos sobre el desempeño de Petróleos Mexicanos.\n\nLa Secretaría Anticorrupción y Buen Gobierno debe determinar los contenidos mínimos de la evaluación que realice la Persona Comisaria, para lo cual debe considerar lo previsto en la Ley.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Segunda — Del Informe"},{"id":"ef72e285-093b-5c32-8907-acfb429ead27","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":71,"identificador":"Artículo 71","contenido":"El informe de evaluación global a que se refiere el artículo 125, fracción I de la Ley, debe hacerse público por medio de las páginas de Internet de Petróleos Mexicanos y de la Secretaría Anticorrupción y Buen Gobierno.\n\nUna vez que el informe al que se refiere el párrafo anterior se entregue a la persona titular del Ejecutivo Federal y a la Cámara de Diputados en los términos de la Ley, Petróleos Mexicanos puede formular los comentarios y aclaraciones que, en su caso, estime convenientes respecto a su contenido.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Segunda — Del Informe"},{"id":"4b4c7b6d-14ac-584b-86e5-e3cf7a876c60","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":72,"identificador":"Artículo 72","contenido":"El informe anual de la persona titular de la Dirección General de Petróleos Mexicanos sobre el desempeño de la empresa pública del Estado, a que se refiere el artículo 50, fracción XIV de la Ley, debe entregarse a la Persona Comisaria a más tardar en el mes de julio de cada año.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","seccion_nombre":"Sección Segunda — Del Informe"},{"id":"a2fef1de-fa02-5ea7-a23e-f50d89256719","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":73,"identificador":"Artículo 73","contenido":"Para efectos de lo dispuesto en los artículos 11, primer párrafo y 16, fracciones VIII y XXIX de la Ley, en relación con la función del Consejo de Administración para aprobar los lineamientos relacionados con la celebración de alianzas estratégicas y asociaciones con personas físicas o morales para llevar a cabo las actividades relacionadas con su objeto, estos deben contener, cuando menos, las directrices y criterios de jerarquización respecto de los diferentes escenarios de inversión de Petróleos Mexicanos y sus empresas filiales.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Segundo — De las Disposiciones Relativas a las Alianzas Estratégicas, Esquemas para Desarrollo Mixto, Asociaciones con Personas Físicas o Morales y Contratos Mixtos","seccion_nombre":null},{"id":"103487c0-8d86-54f3-821a-53093b872777","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":74,"identificador":"Artículo 74","contenido":"Para efectos de los artículos 11, primer párrafo y 16, fracciones VIII, XXIX, XXX y XXXI de la Ley, en relación con la función del Consejo de Administración para aprobar los lineamientos relacionados con esquemas para desarrollo mixto, para realizar las actividades de exploración y extracción de hidrocarburos, estos deben contener, al menos, la definición del modelo financiero, el procedimiento de selección de participantes para los contratos mixtos y el contenido de los contratos mixtos.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Segundo — De las Disposiciones Relativas a las Alianzas Estratégicas, Esquemas para Desarrollo Mixto, Asociaciones con Personas Físicas o Morales y Contratos Mixtos","seccion_nombre":null},{"id":"db3fccf4-1ceb-5f02-9eec-e0225da7a54e","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":75,"identificador":"Artículo 75","contenido":"Para efectos de lo dispuesto en el artículo 65 de la Ley, en relación con lo establecido en artículo 11, segundo párrafo de la Ley del Sector Hidrocarburos, se debe presentar para autorización del Consejo de Administración, la justificación que contenga las razones técnicas, financieras, jurídicas, operativas o comerciales por las que Petróleos Mexicanos no tiene interés o capacidad para realizar el desarrollo de una asignación para desarrollo propio, o bien, de una asignación para desarrollo mixto.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Segundo — De las Disposiciones Relativas a las Alianzas Estratégicas, Esquemas para Desarrollo Mixto, Asociaciones con Personas Físicas o Morales y Contratos Mixtos","seccion_nombre":null},{"id":"9b83ebcc-6919-51d5-baad-977ae327e346","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":76,"identificador":"Artículo 76","contenido":"En caso de terminación anticipada de un contrato mixto relacionado con una asignación para desarrollo mixto, por cualquier causa, la persona titular de la Dirección General de Petróleos Mexicanos debe informar al Consejo de Administración para toma de conocimiento.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Segundo — De las Disposiciones Relativas a las Alianzas Estratégicas, Esquemas para Desarrollo Mixto, Asociaciones con Personas Físicas o Morales y Contratos Mixtos","seccion_nombre":null},{"id":"9177a899-afca-5001-875e-8f63cbc7166e","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":77,"identificador":"Artículo 77","contenido":"Para efectos de lo dispuesto en el artículo 14 de la Ley, cuando el Consejo de Administración apruebe modificaciones a la estructura orgánica básica, el área competente, conforme al Estatuto Orgánico de la Empresa Pública del Estado, Petróleos Mexicanos, debe encargarse de su implementación, así como realizar los cambios necesarios a la estructura orgánica no básica, que garantice en los términos de la Ley, la independencia administrativa, operativa, técnica y de gestión de Petróleos Mexicanos, para la determinación de su estructura.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Tercero — De las Demás Disposiciones","seccion_nombre":null},{"id":"03a87c46-b1d9-5463-bd73-18c3991e82a2","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":78,"identificador":"Artículo 78","contenido":"Para efectos del artículo 16, fracción XXXV de la Ley, se entiende por control o influencia significativa lo señalado en el artículo 2, fracciones III y XI de la Ley del Mercado de Valores, respectivamente.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Tercero — De las Demás Disposiciones","seccion_nombre":null},{"id":"d2be376e-77dc-570e-ad80-8623231f1c57","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":79,"identificador":"Artículo 79","contenido":"En términos del artículo 31 de la Ley, los acuerdos y actas del Consejo de Administración y de sus comités se deben difundir en la página de internet de Petróleos Mexicanos dentro de los diez días hábiles posteriores a su adopción o autorización y, en caso de que se requiera elaborar versiones públicas de dichos documentos, el plazo se extiende por diez días hábiles más.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Tercero — De las Demás Disposiciones","seccion_nombre":null},{"id":"34efe003-375c-5d21-9c87-9039fe325d3e","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":80,"identificador":"Artículo 80","contenido":"Para efectos de lo dispuesto en el artículo 16, fracción XXV de la Ley, los lineamientos que regulen el sistema de control interno deben determinar, en su caso y con apego a las disposiciones aplicables, los niveles de riesgos financieros, legales y operativos, y deben incluir los límites de responsabilidad, que Petróleos Mexicanos debe considerar para el desarrollo de sus funciones.\n\nPetróleos Mexicanos, a través de sus personas representantes, personas consejeras y personas mandatarias, en las empresas filiales, debe realizar las gestiones necesarias para que, en sus consejos de administración, se alineen las actividades con la planeación y visión estratégica de Petróleos Mexicanos y propongan la adopción de mecanismos de coordinación para la implementación del sistema de control interno.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Tercero — De las Demás Disposiciones","seccion_nombre":null},{"id":"b983d1d0-ca2e-58ae-9339-90c5dfe6627f","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":81,"identificador":"Artículo 81","contenido":"Para efectos de lo dispuesto en el artículo 91, último párrafo de la Ley, Petróleos Mexicanos debe coordinarse con las autoridades competentes, así como con los fedatarios públicos que intervienen en las operaciones traslativas de dominio respecto de bienes inmuebles de su propiedad, conforme a las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","capitulo_nombre":"Capítulo Tercero — De las Demás Disposiciones","seccion_nombre":null},{"id":"5455e74a-671e-552e-a9aa-52d8dddd1716","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":82,"identificador":"Transitorio Primero · decreto","contenido":"El presente decreto entra en vigor al día siguiente de su publicación en el Diario Oficial de la Federación.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"539217a8-1149-5088-bf08-7b18f8f29ea9","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":83,"identificador":"Transitorio Segundo · decreto","contenido":"A partir de la entrada en vigor del presente decreto queda abrogado el Reglamento de la Ley de Petróleos Mexicanos, publicado en el Diario Oficial de la Federación el 31 de octubre de 2014 y quedan derogadas todas las disposiciones reglamentarias y administrativas que se opongan a lo establecido por este decreto.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"a92933dc-1689-57b9-8609-5a6241c16914","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":84,"identificador":"Transitorio Tercero · decreto","contenido":"A partir de la entrada en vigor del presente reglamento, todas las referencias que en los ordenamientos jurídicos vigentes se hagan al Reglamento de la Ley de Petróleos Mexicanos, se entienden hechas al presente ordenamiento.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"8a2fd307-5b02-5259-aea5-7a47c2a05581","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":85,"identificador":"Transitorio Cuarto · decreto","contenido":"Las erogaciones que se generen con motivo de la entrada en vigor del presente decreto se deben realizar con cargo al presupuesto autorizado para Petróleos Mexicanos, por lo que no se incrementa su presupuesto regularizable para el presente ejercicio fiscal, ni se deben autorizar recursos adicionales para el ejercicio fiscal que se trate.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"7e0f4e70-c0b7-55a6-ad1c-7a02693a5beb","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":86,"identificador":"Transitorio Quinto · decreto","contenido":"La persona Comisaria de Petróleos Mexicanos debe realizar la evaluación de la empresa conforme al artículo 125 de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos, durante el año 2025, respecto del año 2024, y presentarlo a más tardar el día 31 de diciembre de 2025.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"4ddb9969-18f1-5b30-9f62-f1619e960c46","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":87,"identificador":"Transitorio Sexto · decreto","contenido":"El Consejo de Administración deberá expedir los criterios y lineamientos a que se refieren los artículos 25 y 28 de este Reglamento, dentro de los 180 días naturales siguientes a la entrada en vigor del presente ordenamiento.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"d087ce95-e22e-5f24-80e2-4fdadc7bd456","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":88,"identificador":"Transitorio Séptimo · decreto","contenido":"Las inconformidades, juicios, arbitrajes, procedimientos y trámites de cualquier naturaleza iniciados con anterioridad a la entrada en vigor del presente decreto deben continuar tramitándose hasta su resolución final conforme a las disposiciones vigentes al momento de su inicio.","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null},{"id":"be40f4e9-3149-5374-98b0-8ac8892a8fc0","ley_id":"055c877a-1eb8-5f0b-9fe2-d28bd73afe3b","orden":89,"identificador":"Firmas y expedición","contenido":"Dado en la residencia del Poder Ejecutivo Federal, en Ciudad de México a 26 de noviembre de 2025.- Presidenta de los Estados Unidos Mexicanos, Claudia Sheinbaum Pardo.- Rúbrica.- Secretario de Hacienda y Crédito Público, Édgar Abraham Amador Zamora.- Rúbrica.- Secretaria de Medio Ambiente y Recursos Naturales, Alicia Isabel Adriana Bárcena Ibarra.- Rúbrica.- Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.- Secretaria Anticorrupción y Buen Gobierno, Raquel Buenrostro Sánchez.- Rúbrica.- Secretaria de Ciencia, Humanidades, Tecnología e Innovación, Rosaura Ruiz Gutiérrez.- Rúbrica.","tipo_articulo":"complementario","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"TÍTULO PRIMERO — DE PETRÓLEOS MEXICANOS COMO EMPRESA PÚBLICA DEL ESTADO","orden":0},{"nivel":"capitulo","nombre":"Capítulo Único — Disposiciones Generales","orden":1},{"nivel":"titulo","nombre":"TÍTULO SEGUNDO — DE LA ORGANIZACIÓN E INTEGRACIÓN DEL CONSEJO DE ADMINISTRACIÓN","orden":2},{"nivel":"capitulo","nombre":"Capítulo Primero — Del Nombramiento y Remoción de las Personas Integrantes del Consejo de Administración","orden":3},{"nivel":"capitulo","nombre":"Capítulo Segundo — Del Conflicto de Interés de las Personas Integrantes del Consejo de Administración","orden":4},{"nivel":"capitulo","nombre":"Capítulo Tercero — Del Comité Especial","orden":5},{"nivel":"capitulo","nombre":"Capítulo Cuarto — De las Remuneraciones","orden":6},{"nivel":"capitulo","nombre":"Capítulo Quinto — De los Comités","orden":7},{"nivel":"titulo","nombre":"TÍTULO TERCERO — VIGILANCIA Y AUDITORÍA","orden":8},{"nivel":"capitulo","nombre":"Capítulo Único — Disposiciones Generales","orden":9},{"nivel":"titulo","nombre":"TÍTULO CUARTO — DEL RÉGIMEN ESPECIAL","orden":10},{"nivel":"capitulo","nombre":"Capítulo Primero — De las Empresas Filiales","orden":11},{"nivel":"capitulo","nombre":"Capítulo Segundo — De las Remuneraciones y Austeridad","orden":12},{"nivel":"capitulo","nombre":"Capítulo Tercero — De las Adquisiciones, Arrendamientos, Servicios y Obras","orden":13},{"nivel":"capitulo","nombre":"Capítulo Cuarto — De las Responsabilidades Administrativas","orden":14},{"nivel":"capitulo","nombre":"Capítulo Quinto — Del Presupuesto","orden":15},{"nivel":"capitulo","nombre":"Capítulo Sexto — De la Deuda","orden":16},{"nivel":"capitulo","nombre":"Capítulo Séptimo — De la Sostenibilidad","orden":17},{"nivel":"titulo","nombre":"TÍTULO QUINTO — OTRAS DISPOSICIONES","orden":18},{"nivel":"capitulo","nombre":"Capítulo Primero — De la Evaluación de Petróleos Mexicanos","orden":19},{"nivel":"seccion","nombre":"Sección Primera — De la Persona Comisaria","orden":20},{"nivel":"seccion","nombre":"Sección Segunda — Del Informe","orden":21},{"nivel":"capitulo","nombre":"Capítulo Segundo — De las Disposiciones Relativas a las Alianzas Estratégicas, Esquemas para Desarrollo Mixto, Asociaciones con Personas Físicas o Morales y Contratos Mixtos","orden":22},{"nivel":"capitulo","nombre":"Capítulo Tercero — De las Demás Disposiciones","orden":23}],"fuente":{"name":"RLEPEPM","code":"5775017","url":"https://sidof.segob.gob.mx/notas/docFuente/5775017","sha256":"01791609388ca55de84ed6ac9ae853dcfb3201ece277010a8dceab9a29ea7565","fecha":"03-12-2025","titulo":"Decreto por el que se expide el Reglamento de la Ley de la Empresa Pública del Estado, Petróleos Mexicanos.","format":"html","tables":0,"images":[],"pdf":{"url":"https://www.diputados.gob.mx/LeyesBiblio/regley/Reg_LEPEPM.pdf","sha256":"9080231242a59cbd78d30fb747864bc45cd63d3c4978f37086b01e45343f4244","bytes":367272}}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='055c877a-1eb8-5f0b-9fe2-d28bd73afe3b';
